import DOMPurify from "dompurify";
import { useEffect, useRef, type ElementType } from "react";
import { useAdmin } from "../contexts/AdminContext";
import { useContentContext } from "../contexts/ContentContext";

type ContentType = "text" | "richtext" | "image";

interface EditableNodeProps {
    id: string;
    fallback: string;
    tag?: string;
    type?: ContentType;
    className?: string;
    style?: React.CSSProperties;
    [key: string]: unknown;
}

/**
 * Drop-in replacement generated by the editable Babel plugin.
 * Renders the element normally in view mode (GSAP-safe),
 * and shows a subtle ring + ID label in edit mode.
 * All editing happens through the ContentPanel menu.
 */
export const EditableNode = ({
    id,
    fallback,
    tag = "span",
    type = "text",
    className,
    style,
    ...rest
}: EditableNodeProps) => {
    const { isEditMode } = useAdmin();
    const { getContent, registerField } = useContentContext();
    const ref = useRef<HTMLElement>(null);

    useEffect(() => {
        registerField(id, fallback, type);
    }, [id, fallback, type, registerField]);

    const value = getContent(id, fallback);
    const isOverridden = value !== fallback;

    // --- IMAGE ---
    if (type === "image") {
        const imgStyle: React.CSSProperties = style ?? {};

        return (
            <img
                ref={ref as React.RefObject<HTMLImageElement>}
                src={value || fallback}
                className={className}
                style={imgStyle}
                data-content-id={isEditMode ? id : undefined}
                {...(rest as React.ImgHTMLAttributes<HTMLImageElement>)}
            />
        );
    }

    const Tag = tag as ElementType;

    // --- VIEW MODE ---
    if (!isEditMode) {
        if (isOverridden) {
            return (
                <Tag
                    className={className}
                    style={style}
                    dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(value) }}
                    {...rest}
                />
            );
        }
        return (
            <Tag className={className} style={style} {...rest}>
                {value}
            </Tag>
        );
    }

    // --- EDIT MODE — visual highlight only ---
    if (isOverridden) {
        return (
            <Tag
                ref={ref}
                className={className}
                style={style}
                data-content-id={id}
                dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(value) }}
                {...rest}
            />
        );
    }

    return (
        <Tag
            ref={ref}
            className={className}
            style={style}
            data-content-id={id}
            {...rest}
        >
            {value}
        </Tag>
    );
};
